import React, { forwardRef } from 'react';

interface CustomInputProps {
  label: string;
}

// Create the forwardRef component here
const CustomInput = forwardRef<HTMLInputElement, CustomInputProps>((props, ref) => {
  return (
    <div>
      <label>{props.label}</label>
      <input ref={ref} type="text" placeholder={props.label} />
    </div>
  );
});

// Export the component here
export default CustomInput;

// Create the parent component here
const ParentComponent = () => {
  // Add useRef import and create ref here
  return (
    <div>
      <CustomInput label="Enter text" />
    </div>
  );
};

export { ParentComponent };
